package com.droppy;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * Imports collection log data from the evansloan "Collection Log" RuneLite plugin.
 */
@Slf4j
public class CollectionLogImporter
{
    private final Gson gson;
    private final PlayerDataManager playerDataManager;

    private boolean importedThisSession = false;

    public CollectionLogImporter(Gson gson, PlayerDataManager playerDataManager)
    {
        this.gson = gson;
        this.playerDataManager = playerDataManager;
    }

    public void tryImport(String username)
    {
        if (importedThisSession || username == null || username.isEmpty())
        {
            return;
        }

        try
        {
            Path dataFile = findDataFile(username);
            if (dataFile == null || !Files.exists(dataFile))
            {
                log.debug("No Collection Log plugin data found for {}", username);
                return;
            }

            String json = Files.readString(dataFile);
            JsonObject root = gson.fromJson(json, JsonObject.class);
            if (root == null || !root.has("tabs"))
            {
                return;
            }

            int itemsImported = 0;
            int kcImported = 0;
            int pagesImported = 0;

            JsonObject tabs = root.getAsJsonObject("tabs");
            for (Map.Entry<String, JsonElement> tabEntry : tabs.entrySet())
            {
                if (!tabEntry.getValue().isJsonObject())
                {
                    continue;
                }

                JsonObject pages = tabEntry.getValue().getAsJsonObject();
                for (Map.Entry<String, JsonElement> pageEntry : pages.entrySet())
                {
                    if (!pageEntry.getValue().isJsonObject())
                    {
                        continue;
                    }

                    String pageName = pageEntry.getKey();
                    JsonObject page = pageEntry.getValue().getAsJsonObject();

                    // Skip pages that haven't been opened in-game
                    if (!page.has("isUpdated") || !page.get("isUpdated").getAsBoolean())
                    {
                        continue;
                    }

                    if (page.has("items") && page.get("items").isJsonArray())
                    {
                        for (JsonElement itemEl : page.getAsJsonArray("items"))
                        {
                            if (!itemEl.isJsonObject())
                            {
                                continue;
                            }

                            JsonObject item = itemEl.getAsJsonObject();
                            boolean obtained = item.has("obtained")
                                && item.get("obtained").getAsBoolean();
                            String itemName = item.has("name")
                                ? item.get("name").getAsString() : null;
                            int itemId = item.has("id")
                                ? item.get("id").getAsInt() : -1;

                            if (itemName == null || itemName.isEmpty())
                            {
                                continue;
                            }

                            if (itemId > 0)
                            {
                                playerDataManager.addClogItem(itemName, itemId);
                            }

                            if (obtained && !playerDataManager.hasItem(itemName))
                            {
                                playerDataManager.markItemObtainedFromSync(itemName);
                                itemsImported++;
                            }
                        }
                    }

                    if (page.has("killCounts") && page.get("killCounts").isJsonArray())
                    {
                        for (JsonElement kcEl : page.getAsJsonArray("killCounts"))
                        {
                            if (!kcEl.isJsonObject())
                            {
                                continue;
                            }

                            JsonObject kc = kcEl.getAsJsonObject();
                            int amount = kc.has("amount") ? kc.get("amount").getAsInt() : 0;

                            if (amount > 0)
                            {
                                int currentKc = playerDataManager.getKillCount(pageName);
                                if (amount > currentKc)
                                {
                                    playerDataManager.setKillCount(pageName, amount);
                                    kcImported++;
                                }
                            }
                        }
                    }

                    playerDataManager.markPageSynced(pageName);
                    pagesImported++;
                }
            }

            if (itemsImported > 0 || kcImported > 0)
            {
                playerDataManager.savePlayerData();
                log.info("Imported from Collection Log plugin: {} items, {} KC entries, {} pages",
                    itemsImported, kcImported, pagesImported);
            }
            else
            {
                log.debug("Collection Log plugin data found but no new data to import");
            }

            importedThisSession = true;
        }
        catch (Exception e)
        {
            log.debug("Could not import Collection Log plugin data: {}", e.getMessage());
            importedThisSession = true;
        }
    }

    public void resetSession()
    {
        importedThisSession = false;
    }

    private Path findDataFile(String username)
    {
        String userHome = System.getProperty("user.home");
        if (userHome == null)
        {
            return null;
        }

        File runeliteDir = new File(userHome, ".runelite");
        if (!runeliteDir.exists())
        {
            return null;
        }

        File dataFile = new File(runeliteDir,
            "collectionlog" + File.separator
                + "data" + File.separator
                + username + File.separator
                + "collectionlog-" + username + ".json");

        if (dataFile.exists())
        {
            return dataFile.toPath();
        }

        return null;
    }
}

package com.droppy;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

@Slf4j
public class CollectionLogManager
{
    private static final int COLLECTION_LOG_GROUP = 621;
    private static final int ENTRY_HEADER_CHILD = 20;
    private static final int ENTRY_ITEMS_CHILD = 37;
    private static final int ENTRY_TITLE_INDEX = 0;

    private final Client client;
    private final ItemManager itemManager;
    private final PlayerDataManager playerDataManager;

    private String lastScrapedPage;

    public CollectionLogManager(Client client, ItemManager itemManager,
                                PlayerDataManager playerDataManager)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.playerDataManager = playerDataManager;
    }

    public void onCollectionLogPageRendered()
    {
        try
        {
            scrapeCurrentPage();
        }
        catch (Exception e)
        {
            log.warn("Failed to scrape collection log page: {}", e.getMessage());
        }
    }

    private void scrapeCurrentPage()
    {
        Widget entryHeader = client.getWidget(COLLECTION_LOG_GROUP, ENTRY_HEADER_CHILD);
        if (entryHeader == null)
        {
            return;
        }

        Widget[] headerChildren = entryHeader.getDynamicChildren();
        if (headerChildren == null || headerChildren.length < 1)
        {
            return;
        }

        String pageTitle = headerChildren[ENTRY_TITLE_INDEX].getText();
        if (pageTitle == null || pageTitle.isEmpty())
        {
            return;
        }

        pageTitle = stripTags(pageTitle);

        log.debug("Scraping collection log page: {}", pageTitle);

        parseKillCounts(pageTitle, headerChildren);
        parseItems(pageTitle);

        playerDataManager.markPageSynced(pageTitle);
        lastScrapedPage = pageTitle;
        playerDataManager.savePlayerData();
    }

    private void parseKillCounts(String pageTitle, Widget[] headerChildren)
    {
        for (int i = 2; i < headerChildren.length; i++)
        {
            String text = headerChildren[i].getText();
            if (text == null || text.isEmpty())
            {
                continue;
            }

            text = stripTags(text);

            int colonIdx = text.indexOf(':');
            if (colonIdx < 0)
            {
                continue;
            }

            String kcType = text.substring(0, colonIdx).trim();
            String kcValueStr = text.substring(colonIdx + 1).trim().replace(",", "");

            try
            {
                int kcValue = Integer.parseInt(kcValueStr);
                playerDataManager.setKillCount(pageTitle, kcValue);
                log.debug("Collection log KC for {} ({}): {}", pageTitle, kcType, kcValue);
            }
            catch (NumberFormatException e)
            {
                log.debug("Could not parse KC value '{}' for {}", kcValueStr, pageTitle);
            }
        }
    }

    private void parseItems(String pageTitle)
    {
        Widget itemsContainer = client.getWidget(COLLECTION_LOG_GROUP, ENTRY_ITEMS_CHILD);
        if (itemsContainer == null)
        {
            return;
        }

        Widget[] itemWidgets = itemsContainer.getDynamicChildren();
        if (itemWidgets == null)
        {
            return;
        }

        int obtainedCount = 0;

        for (Widget itemWidget : itemWidgets)
        {
            int itemId = itemWidget.getItemId();
            if (itemId <= 0)
            {
                continue;
            }

            String itemName = itemManager.getItemComposition(itemId).getName();
            if (itemName == null || itemName.isEmpty())
            {
                continue;
            }

            playerDataManager.addClogItem(itemName, itemId);

            boolean obtained = itemWidget.getOpacity() == 0;

            if (obtained)
            {
                obtainedCount++;
                playerDataManager.markItemObtainedFromSync(itemName);
                log.debug("  Obtained: {} (id={})", itemName, itemId);
            }
            else
            {
                playerDataManager.markItemNotObtained(itemName, pageTitle);
                log.debug("  Missing: {} (id={})", itemName, itemId);
            }
        }

        log.debug("Scraped {} items from {}: {} obtained",
            itemWidgets.length, pageTitle, obtainedCount);
    }

    public boolean isCollectionLogOpen()
    {
        Widget container = client.getWidget(COLLECTION_LOG_GROUP, ENTRY_ITEMS_CHILD);
        return container != null && !container.isHidden();
    }

    public String getLastScrapedPage()
    {
        return lastScrapedPage;
    }

    private static String stripTags(String text)
    {
        return text.replaceAll("<[^>]+>", "").trim();
    }
}

package com.droppy;

// P(at least 1 drop in N kills) = 1 - (1 - dropRate)^N
public class DropChanceCalculator
{
    public static double calculateChance(double dropRate, int killCount)
    {
        if (dropRate <= 0 || killCount <= 0)
        {
            return 0.0;
        }

        if (dropRate >= 1.0)
        {
            return 1.0;
        }

        return 1.0 - Math.pow(1.0 - dropRate, killCount);
    }

    public static String formatPercent(double probability)
    {
        if (probability <= 0)
        {
            return "0%";
        }
        if (probability >= 1.0)
        {
            return "100%";
        }

        double percent = probability * 100.0;

        if (percent < 0.01)
        {
            return "<0.01%";
        }

        // Full precision
        if (percent >= 10.0)
        {
            return String.format("%.2f%%", percent);
        }
        return String.format("%.4f%%", percent);
    }

    // n = log(1 - P) / log(1 - r)
    public static int killsForProbability(double dropRate, double targetProbability)
    {
        if (dropRate <= 0 || dropRate >= 1.0 || targetProbability <= 0 || targetProbability >= 1.0)
        {
            return -1;
        }

        return (int) Math.ceil(Math.log(1.0 - targetProbability) / Math.log(1.0 - dropRate));
    }

    public static String expectedKills(double dropRate)
    {
        if (dropRate <= 0)
        {
            return "N/A";
        }
        return String.format("%,d kc", Math.round(1.0 / dropRate));
    }

    public static String formatDropRate(double dropRate)
    {
        if (dropRate <= 0)
        {
            return "N/A";
        }
        if (dropRate >= 1.0)
        {
            return "Always";
        }

        long denominator = Math.round(1.0 / dropRate);
        return "1/" + String.format("%,d", denominator);
    }
}

